#!/usr/bin/env node
/**
 * scripts/verify-cli.mjs — the verify:cli gate (3.3.0 "Zero-Dependency npx CLI Scaffolder").
 * ----------------------------------------------------------------------------
 * Pure fs/process assertions — no browser, no external deps. Three layers:
 *
 *   SCENARIOS (run the real CLI in throwaway /tmp dirs):
 *     A  mock React project (vite.config.ts + vite dep) — bento + oled:
 *        exit 0 · resolved oled tokens (#000000/#0B0C10) · "generated by"
 *        header · SignatureStarter.tsx (sig-shell/bento12, vanilla hooks) ·
 *        signature-bento.css companion · README-SIGNATURE.md · existing
 *        files byte-untouched.
 *     B  mock HTML project (index.html only) — minimal + daylight:
 *        daylight tokens (#FFFFFF/#F1F5F9 + the ink variants #A16207 /
 *        #3F6212) · NO starter files (minimal scaffolds none).
 *     C  safe injection — pre-written sentinel tokens: without --force the
 *        sentinel survives ([skip]); with --force it is replaced by the
 *        mocha values ([overwrite]).
 *     D  detection labels — folded into A ("vite-react") and B ("html").
 *
 *   GATES:
 *     cli1  bin/cli.mjs exists · shebang first line · every import specifier
 *           is node: or relative (zero external deps) · themes.mjs is a pure
 *           data module (no imports at all).
 *     cli2  THE DRIFT NEEDLE — bin/themes.mjs mocha tokens must equal the
 *           css/tokens.css :root block declaration-for-declaration. If
 *           tokens.css mocha values ever change, this gate FAILS and the
 *           CLI map must be regenerated.
 *     cli3  package.json wiring — bin entry, files += "bin", both scripts.
 *     b3    `npm pack --dry-run` reports EXACTLY 60 files (the 58-file
 *           3.2.0 tarball + bin/cli.mjs + bin/themes.mjs — the CLI ships
 *           both: cli.mjs imports themes.mjs at npx runtime).
 *
 * Cleanup: every tmp dir dies in a finally. Exit 0 only when ALL green.
 */

import { spawnSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { THEMES } from "../bin/themes.mjs";

const root = resolve(join(fileURLToPath(import.meta.url), "..", ".."));
const CLI = join(root, "bin", "cli.mjs");
const failures = [];
let passed = 0;

/**
 * Record one assertion, printing it live.
 *
 * @param {boolean} ok
 * @param {string} label
 * @param {string} [detail] - printed only on failure
 */
function check(ok, label, detail = "") {
  if (ok) {
    passed += 1;
    process.stdout.write(`  \u2713 ${label}\n`);
  } else {
    failures.push(detail ? `${label} — ${detail}` : label);
    process.stdout.write(`  \u2717 ${label}${detail ? ` — ${detail}` : ""}\n`);
  }
}

/**
 * Read a file or return "" when absent (readability of generated artifacts).
 *
 * @param {string} path
 * @returns {string}
 */
function read(path) {
  return existsSync(path) ? readFileSync(path, "utf8") : "";
}

/**
 * Run the CLI's init in the given cwd.
 *
 * @param {string} dir - the mock project directory (also the CLI's --dir target)
 * @param {string[]} args - extra flags after "init"
 * @returns {{status: number|null, stdout: string, stderr: string}}
 */
function runInit(dir, args) {
  const res = spawnSync(process.execPath, [CLI, "init", "--dir", dir, ...args], {
    cwd: dir,
    encoding: "utf8",
  });
  return { status: res.status, stdout: res.stdout ?? "", stderr: res.stderr ?? "" };
}

// ---------------------------------------------------------------------------
// Scenario A — mock React (vite.config.ts + vite dep) · bento · oled
// ---------------------------------------------------------------------------
function scenarioA() {
  process.stdout.write("\nscenario A — mock React (vite) \u00b7 bento \u00b7 oled\n");
  const dir = mkdtempSync(join(tmpdir(), "sig-cli-a-"));
  try {
    const viteConfig = "export default {};\n";
    const pkgJson = JSON.stringify({ dependencies: { vite: "^5.0.0" } });
    writeFileSync(join(dir, "vite.config.ts"), viteConfig);
    writeFileSync(join(dir, "package.json"), pkgJson);

    const res = runInit(dir, ["--template", "bento", "--theme", "oled", "--yes"]);
    check(res.status === 0, "A \u00b7 exit 0", `status ${res.status}; stderr: ${res.stderr.slice(0, 300)}`);
    check(res.stdout.includes("Next steps"), "A \u00b7 summary printout");

    const tokens = read(join(dir, "signature-tokens.css"));
    check(tokens.length > 0, "A \u00b7 signature-tokens.css written");
    check(tokens.includes("#000000") && tokens.includes("#0B0C10"), "A \u00b7 oled true-black surfaces (#000000 / #0B0C10)");
    check(tokens.includes("generated by @edwyn/signature-style init"), "A \u00b7 \"generated by\" header");
    check(tokens.includes("--radius-ui: 8px") && tokens.includes("--radius-card: 12px"), "A \u00b7 standard geometry baked (8px / 12px)");
    check(tokens.includes("--sig-cobalt: #89b4fa"), "A \u00b7 chromatic inheritance present");

    const tsx = read(join(dir, "SignatureStarter.tsx"));
    check(tsx.includes("sig-shell") && tsx.includes("bento12"), "A \u00b7 SignatureStarter.tsx carries sig-shell + the bento grid");
    check(tsx.includes("useState"), "A \u00b7 vanilla React hooks (standalone)");
    check(!/from\s*["']@edwyn\/signature-style/.test(tsx), "A \u00b7 zero package component imports");

    check(existsSync(join(dir, "signature-bento.css")), "A \u00b7 signature-bento.css companion written");
    check(existsSync(join(dir, "README-SIGNATURE.md")), "A \u00b7 README-SIGNATURE.md written");

    check(read(join(dir, "vite.config.ts")) === viteConfig, "A \u00b7 existing vite.config.ts byte-untouched");
    check(read(join(dir, "package.json")) === pkgJson, "A \u00b7 existing package.json byte-untouched");

    check(res.stdout.includes("vite-react"), "D \u00b7 detection reports \"vite-react\" (A)");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

// ---------------------------------------------------------------------------
// Scenario B — mock HTML (index.html only) · minimal · daylight
// ---------------------------------------------------------------------------
function scenarioB() {
  process.stdout.write("\nscenario B — mock HTML (index.html) \u00b7 minimal \u00b7 daylight\n");
  const dir = mkdtempSync(join(tmpdir(), "sig-cli-b-"));
  try {
    writeFileSync(join(dir, "index.html"), "<!doctype html>\n<html></html>\n");

    const res = runInit(dir, ["--template", "minimal", "--theme", "daylight", "--yes"]);
    check(res.status === 0, "B \u00b7 exit 0", `status ${res.status}; stderr: ${res.stderr.slice(0, 300)}`);

    const tokens = read(join(dir, "signature-tokens.css"));
    check(tokens.includes("#FFFFFF") && tokens.includes("#F1F5F9"), "B \u00b7 daylight surfaces (#FFFFFF / #F1F5F9)");
    check(tokens.includes("--sig-yellow: #A16207"), "B \u00b7 daylight ink variant present (yellow \u2192 amber)");
    check(tokens.includes("--sig-lime-glow: #3F6212"), "B \u00b7 daylight chromatic ink present (lime-glow)");
    check(tokens.includes("--bg-base: #F8FAFC"), "B \u00b7 daylight slate structure");

    check(!existsSync(join(dir, "SignatureStarter.tsx")), "B \u00b7 minimal creates NO tsx starter");
    check(!existsSync(join(dir, "signature-starter.html")), "B \u00b7 minimal creates NO html starter");
    check(!existsSync(join(dir, "signature-bento.css")), "B \u00b7 minimal creates NO companion css");
    check(existsSync(join(dir, "README-SIGNATURE.md")), "B \u00b7 README-SIGNATURE.md written");

    check(res.stdout.includes("html"), "D \u00b7 detection reports \"html\" (B)");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

// ---------------------------------------------------------------------------
// Scenario C — safe injection: sentinel survives without --force, dies with it
// ---------------------------------------------------------------------------
function scenarioC() {
  process.stdout.write("\nscenario C — safe injection \u00b7 sentinel \u00b7 mocha\n");
  const dir = mkdtempSync(join(tmpdir(), "sig-cli-c-"));
  try {
    const sentinel = "/* SENTINEL — this pre-existing file must not be clobbered */";
    writeFileSync(join(dir, "signature-tokens.css"), sentinel);

    const first = runInit(dir, ["--theme", "mocha", "--yes"]);
    check(first.status === 0, "C \u00b7 skip run exit 0", `status ${first.status}`);
    check(first.stdout.includes("[skip]"), "C \u00b7 stdout carries the [skip] notice");
    check(read(join(dir, "signature-tokens.css")) === sentinel, "C \u00b7 sentinel intact without --force");

    const second = runInit(dir, ["--theme", "mocha", "--force", "--yes"]);
    check(second.status === 0, "C \u00b7 force run exit 0", `status ${second.status}`);
    const overwritten = read(join(dir, "signature-tokens.css"));
    check(!overwritten.includes("SENTINEL"), "C \u00b7 sentinel replaced under --force");
    check(overwritten.includes("--bg-base: #1E1E2E") && overwritten.includes("--sig-cobalt: #89b4fa"), "C \u00b7 replaced file carries the mocha values");
    check(second.stdout.includes("[overwrite]"), "C \u00b7 stdout carries the [overwrite] notice");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

// ---------------------------------------------------------------------------
// Gate cli1 — shebang + zero external imports
// ---------------------------------------------------------------------------
/**
 * Strip comments and TEMPLATE literals from source, keeping plain strings
 * — the gate needs to READ real import specifiers (always plain strings)
 * while ignoring the embedded starter templates (backtick spans whose
 * content legitimately says `import ... from "react"` as text) and the
 * header comments (whose own backticks/quotes would otherwise start fake
 * literals). One pass; escapes and `${...}` interpolation honored.
 *
 * @param {string} src
 * @returns {string} source with comments/templates blanked
 */
function stripCommentsAndTemplates(src) {
  let out = "";
  let i = 0;
  while (i < src.length) {
    const ch = src[i];
    const next = src[i + 1];
    if (ch === "/" && next === "/") {
      while (i < src.length && src[i] !== "\n") i += 1;
      continue;
    }
    if (ch === "/" && next === "*") {
      i += 2;
      while (i < src.length && !(src[i] === "*" && src[i + 1] === "/")) i += 1;
      i += 2;
      out += " ";
      continue;
    }
    if (ch === "`") {
      i = skipTemplate(src, i);
      out += "`T`";
      continue;
    }
    if (ch === '"' || ch === "'") {
      const quote = ch;
      out += quote;
      i += 1;
      while (i < src.length && src[i] !== quote) {
        if (src[i] === "\\") i += 2;
        else { out += src[i]; i += 1; }
      }
      out += quote;
      i += 1;
      continue;
    }
    out += ch;
    i += 1;
  }
  return out;
}

/**
 * Skip one template literal (backtick span with `${...}` interpolation);
 *
 * @param {string} src
 * @param {number} start - index of the opening backtick
 * @returns {number} index OF the closing backtick
 */
function skipTemplate(src, start) {
  let i = start + 1;
  while (i < src.length) {
    if (src[i] === "\\") { i += 2; continue; }
    if (src[i] === "`") return i;
    if (src[i] === "$" && src[i + 1] === "{") {
      let depth = 1;
      i += 2;
      while (i < src.length && depth > 0) {
        if (src[i] === "{") depth += 1;
        else if (src[i] === "}") depth -= 1;
        else if (src[i] === "`") i = skipTemplate(src, i);
        else if (src[i] === '"' || src[i] === "'") {
          const quote = src[i];
          i += 1;
          while (i < src.length && src[i] !== quote) {
            if (src[i] === "\\") i += 2;
            else i += 1;
          }
        }
        i += 1;
      }
      continue;
    }
    i += 1;
  }
  return i;
}

/**
 * Gate cli1 — shebang + zero external imports.
 */
function gateCli1() {
  process.stdout.write("\ngate cli1 — zero external dependencies\n");
  check(existsSync(CLI), "cli1 \u00b7 bin/cli.mjs exists");
  const src = read(CLI);
  check(src.startsWith("#!/usr/bin/env node"), "cli1 \u00b7 shebang is the first line");
  const real = stripCommentsAndTemplates(src);
  const specifiers = [...real.matchAll(/import\s[^\n]*?from\s*["']([^"']+)["']|import\s*["']([^"']+)["']/g)]
    .map((m) => m[1] ?? m[2]);
  check(specifiers.length > 0, "cli1 \u00b7 import lines found", "no imports found — parser regression?");
  const external = specifiers.filter((s) => !(s.startsWith("node:") || s.startsWith("./") || s.startsWith("../")));
  check(external.length === 0, "cli1 \u00b7 every import is node: or relative", external.join(", "));
  const themesSrc = read(join(root, "bin", "themes.mjs"));
  check(!/^import[\s ]/m.test(themesSrc), "cli1 \u00b7 bin/themes.mjs is a pure data module (no imports)");
}

// ---------------------------------------------------------------------------
// Gate cli2 — THE DRIFT NEEDLE: themes.mjs mocha == tokens.css :root
// ---------------------------------------------------------------------------
/**
 * Parse the single :root block of css/tokens.css into a flat value map
 * (comments stripped, whitespace collapsed).
 *
 * @returns {{map: Record<string, string>, order: string[]}}
 */
function parseTokensRoot() {
  const css = readFileSync(join(root, "css", "tokens.css"), "utf8");
  const block = css.match(/:root \{\n([\s\S]*?)\n  \}/);
  if (!block) throw new Error("cli2: could not locate the :root block in css/tokens.css");
  const clean = block[1].replace(/\/\*[\s\S]*?\*\//g, "");
  const map = {};
  const order = [];
  for (const decl of clean.split(";")) {
    const idx = decl.indexOf(":");
    if (idx === -1) continue;
    const key = decl.slice(0, idx).trim();
    if (!key.startsWith("--")) continue;
    const value = decl.slice(idx + 1).trim().replace(/\s+/g, " ");
    map[key] = value;
    order.push(key);
  }
  return { map, order };
}

function gateCli2() {
  process.stdout.write("\ngate cli2 — theme drift needle (themes.mjs vs tokens.css :root)\n");
  const parsed = parseTokensRoot();
  const mocha = THEMES.mocha.tokens;
  const drifted = Object.keys(mocha).filter((key) => mocha[key] !== parsed.map[key]);
  const unmapped = parsed.order.filter((key) => !(key in mocha));
  const stale = Object.keys(mocha).filter((key) => !(key in parsed.map));
  check(
    drifted.length === 0 && unmapped.length === 0 && stale.length === 0,
    `cli2 \u00b7 themes.mocha mirrors tokens.css :root exactly (${parsed.order.length} declarations)`,
    `drifted: ${drifted.join(", ") || "none"} \u00b7 unmapped-in-map: ${unmapped.join(", ") || "none"} \u00b7 stale-in-map: ${stale.join(", ") || "none"}`,
  );
}

// ---------------------------------------------------------------------------
// Gate cli3 — package.json wiring
// ---------------------------------------------------------------------------
function gateCli3() {
  process.stdout.write("\ngate cli3 — package.json wiring\n");
  const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8"));
  check(pkg.bin && pkg.bin["signature-style"] === "./bin/cli.mjs", "cli3 \u00b7 bin entry wired");
  check(Array.isArray(pkg.files) && pkg.files.includes("bin"), "cli3 \u00b7 files array ships bin");
  check(pkg.scripts && pkg.scripts.cli === "node bin/cli.mjs", "cli3 \u00b7 scripts.cli wired");
  check(pkg.scripts && pkg.scripts["verify:cli"] === "node scripts/verify-cli.mjs", "cli3 \u00b7 scripts.verify:cli wired");
}

// ---------------------------------------------------------------------------
// Gate b3 — the tarball grows 60 → EXACTLY 64
// ---------------------------------------------------------------------------
function gatePack() {
  process.stdout.write("\ngate b3 — pack expectation\n");
  const res = spawnSync("npm", ["pack", "--dry-run"], { cwd: root, encoding: "utf8" });
  // npm prints the notice lines (incl. "total files:") on STDERR
  const notice = `${res.stdout ?? ""}\n${res.stderr ?? ""}`;
  const match = notice.match(/total files:\s*(\d+)/);
  const total = match ? Number(match[1]) : -1;
  // 60 (the 3.3.0 tarball) + the dist/wc quartet — signature-wc.es.js +
  // index.d.ts + base.d.ts + elements.d.ts: the compiled bundle AND the
  // tsc-honest declarations ship (the wc/src sources stay out, like the
  // react .tsx sources).
  check(total === 64, "b3 \u00b7 pack reports EXACTLY 64 files (60 + the dist/wc quartet: signature-wc.es.js + index.d.ts + base.d.ts + elements.d.ts)", `found ${total}`);
}

// ---------------------------------------------------------------------------
// run everything
// ---------------------------------------------------------------------------
for (const layer of [scenarioA, scenarioB, scenarioC, gateCli1, gateCli2, gateCli3, gatePack]) {
  layer();
}

if (failures.length > 0) {
  process.stderr.write(`\nFAIL — verify:cli: ${failures.length} failing check(s) of ${passed + failures.length}\n`);
  for (const failure of failures) process.stderr.write(`  \u2717 ${failure}\n`);
  process.exitCode = 1;
} else {
  process.stdout.write(`\nPASS — verify:cli: ${passed} checks green (scenarios A\u2013D + gates cli1/cli2/cli3/b3; tmp dirs cleaned)\n`);
}
